/* Generador de imagen OG — herramienta interna */
  const LOGO_SRC = "data:image/png;base64,";
  const FOTO_PREDETERMINADA = "https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?q=80&w=1800&auto=format&fit=crop";
  const C = { negro:'#0D0D0D', negroSuave:'#1A1A1A', dorado:'#C9A961', doradoClaro:'#E4CD8F', doradoOscuro:'#8A6E2F', hueso:'#F8F6F2' };

  const canvas = document.getElementById('og');
  const ctx = canvas.getContext('2d');
  const estado = document.getElementById('estado');
  const btnDescargar = document.getElementById('descargar');
  let foto = null;
  let logo = null;

  const cargarImagen = (src, cors) => new Promise((resolve) => {
    const img = new Image();
    if (cors) img.crossOrigin = 'anonymous';
    img.onload = () => resolve(img);
    img.onerror = () => resolve(null);
    img.src = src;
  });

  function rect(x, y, w, h, r) {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
  }

  // Texto con espaciado entre letras (tracking) compatible con todos los navegadores
  function textoEspaciado(texto, x, y, espaciado, alinear = 'left') {
    const ancho = [...texto].reduce((t, ch) => t + ctx.measureText(ch).width + espaciado, -espaciado);
    let cx = alinear === 'center' ? x - ancho / 2 : x;
    ctx.textAlign = 'left';
    [...texto].forEach(ch => { ctx.fillText(ch, cx, y); cx += ctx.measureText(ch).width + espaciado; });
    return ancho;
  }

  function dibujarFotoCover(img, x, y, w, h) {
    const escala = Math.max(w / img.width, h / img.height);
    const iw = img.width * escala, ih = img.height * escala;
    ctx.drawImage(img, x + (w - iw) / 2, y + (h - ih) / 2, iw, ih);
  }

  function dibujar() {
    const W = 1200, H = 630;
    ctx.clearRect(0, 0, W, H);

    // Fondo: foto + degradado negro desde la izquierda
    ctx.fillStyle = C.negro;
    ctx.fillRect(0, 0, W, H);
    if (foto) dibujarFotoCover(foto, 380, 0, W - 380, H);
    else {
      const g = ctx.createRadialGradient(950, 120, 40, 950, 120, 700);
      g.addColorStop(0, 'rgba(201,169,97,.35)'); g.addColorStop(1, 'rgba(13,13,13,0)');
      ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
    }
    const sombra = ctx.createLinearGradient(0, 0, W, 0);
    sombra.addColorStop(0, 'rgba(13,13,13,1)');
    sombra.addColorStop(0.36, 'rgba(13,13,13,.96)');
    sombra.addColorStop(0.58, 'rgba(13,13,13,.45)');
    sombra.addColorStop(1, 'rgba(13,13,13,.05)');
    ctx.fillStyle = sombra; ctx.fillRect(0, 0, W, H);
    const viñeta = ctx.createLinearGradient(0, H, 0, H - 220);
    viñeta.addColorStop(0, 'rgba(13,13,13,.6)'); viñeta.addColorStop(1, 'rgba(13,13,13,0)');
    ctx.fillStyle = viñeta; ctx.fillRect(0, H - 220, W, 220);

    // Panel de cristal
    const px = 44, py = 44, pw = 588, ph = 542;
    ctx.save();
    rect(px, py, pw, ph, 22);
    ctx.fillStyle = 'rgba(26,26,26,.62)'; ctx.fill();
    ctx.lineWidth = 1.5; ctx.strokeStyle = 'rgba(201,169,97,.45)'; ctx.stroke();
    ctx.restore();
    const brillo = ctx.createLinearGradient(px + 30, 0, px + pw - 30, 0);
    brillo.addColorStop(0, 'rgba(201,169,97,0)'); brillo.addColorStop(.5, C.dorado); brillo.addColorStop(1, 'rgba(201,169,97,0)');
    ctx.fillStyle = brillo; ctx.fillRect(px + 30, py - 0.5, pw - 60, 1.5);

    // Logo horizontal (hueso y dorado, fondo transparente) directo sobre el panel oscuro
    const bx = px + 40, by = py + 40, bw = pw - 80, bh = 158;
    if (logo) {
      const lw = bw - 20, lh = lw * (logo.height / logo.width);
      ctx.drawImage(logo, bx + 4, by + (bh - lh) / 2, lw, lh);
    }

    // Eyebrow
    const tx = px + 42;
    ctx.fillStyle = C.dorado; ctx.fillRect(tx, by + bh + 52, 26, 1.5);
    ctx.font = '600 15px "Montserrat"'; ctx.fillStyle = C.doradoClaro; ctx.textBaseline = 'middle';
    textoEspaciado('BIENES RAÍCES · ZMG', tx + 40, by + bh + 53, 3.6);

    // Titular
    ctx.textBaseline = 'alphabetic';
    ctx.font = '700 44px "Playfair Display"'; ctx.fillStyle = C.hueso;
    ctx.fillText('Exclusividad, Inversión', tx, by + bh + 118);
    ctx.fillText('y un ', tx, by + bh + 170);
    const anchoYun = ctx.measureText('y un ').width;
    ctx.fillStyle = C.doradoClaro;
    ctx.fillText('Estilo de Vida', tx + anchoYun, by + bh + 170);

    // Cobertura
    ctx.font = '400 17px "Montserrat"'; ctx.fillStyle = '#D8D3C9';
    ctx.fillText('Guadalajara · Zapopan · Riviera de Chapala · Costa de Jalisco', tx, by + bh + 212);

    // Línea + contacto
    const ly = py + ph - 74;
    ctx.fillStyle = 'rgba(201,169,97,.35)'; ctx.fillRect(tx, ly, pw - 84, 1);
    ctx.font = '600 17px "Montserrat"'; ctx.fillStyle = C.hueso; ctx.textBaseline = 'middle';
    ctx.fillText('inmobiliariademetrius.com', tx, ly + 38);
    ctx.textAlign = 'right'; ctx.fillStyle = C.doradoClaro;
    ctx.fillText('WhatsApp 33 5107 0944', px + pw - 42, ly + 38);
    ctx.textAlign = 'left';

    // Motivo de ventanas (del logo) en la esquina inferior derecha
    ctx.fillStyle = C.dorado;
    [[0,0],[1,0],[0,1],[1,1]].forEach(([i, j]) => ctx.fillRect(W - 66 + i * 12, H - 66 + j * 12, 9, 9));

    const medida = document.createElement('b');
    medida.textContent = '1200 × 630 px';
    estado.replaceChildren('Listo · ', medida, foto ? '' : ' · sin foto de fondo (sube una o revisa tu conexión)');
    btnDescargar.disabled = false;
  }

  async function iniciar() {
    await Promise.all([
      document.fonts.load('700 44px "Playfair Display"'),
      document.fonts.load('400 17px "Montserrat"'),
      document.fonts.load('600 17px "Montserrat"')
    ]).catch(() => {});
    [logo, foto] = await Promise.all([cargarImagen(LOGO_SRC, false), cargarImagen(FOTO_PREDETERMINADA, true)]);
    dibujar();
  }

  btnDescargar.addEventListener('click', () => {
    try {
      canvas.toBlob((blob) => {
        const a = document.createElement('a');
        a.href = URL.createObjectURL(blob);
        a.download = 'og-preview.jpg';
        document.body.appendChild(a); a.click(); a.remove();
        setTimeout(() => URL.revokeObjectURL(a.href), 2000);
        const peso = document.createElement('b');
        peso.textContent = `${Math.round(blob.size / 1024)} KB`;
        estado.replaceChildren('Descargado · ', peso, ' · 1200 × 630 px');
      }, 'image/jpeg', 0.88);
    } catch (e) {
      estado.textContent = 'La foto de fondo no permite exportar. Sube una foto desde tu equipo.';
    }
  });

  document.getElementById('foto').addEventListener('change', (e) => {
    const archivo = e.target.files && e.target.files[0];
    if (!archivo) return;
    const lector = new FileReader();
    lector.onload = async () => { foto = await cargarImagen(lector.result, false); dibujar(); };
    lector.readAsDataURL(archivo);
  });
  document.getElementById('restaurar').addEventListener('click', async () => {
    foto = await cargarImagen(FOTO_PREDETERMINADA, true); dibujar();
  });

  iniciar();
